# Builds the signed release AAB with the existing android/ project (no prebuild: the custom
# Kotlin alarm/widget code under android/ is not generated by any plugin and must not be wiped).
#
#   powershell -NoProfile -ExecutionPolicy Bypass -File .\scripts\build-release.ps1
#   powershell -NoProfile -ExecutionPolicy Bypass -File .\scripts\build-release.ps1 -ShutdownWhenDone
#
# -ShutdownWhenDone powers the PC off after a SUCCESSFUL build, with a 2 minute countdown
# (cancel with: shutdown /a). A failed build never shuts the computer down.
param([switch]$ShutdownWhenDone)

$ErrorActionPreference = 'Stop'
Set-Location (Join-Path $PSScriptRoot '..\android')

& .\gradlew.bat bundleRelease '-PreactNativeArchitectures=arm64-v8a,armeabi-v7a'
$exitCode = $LASTEXITCODE

$aab = Join-Path (Get-Location) 'app\build\outputs\bundle\release\app-release.aab'
if ($exitCode -eq 0 -and (Test-Path $aab)) {
  $item = Get-Item $aab
  Write-Host ''
  Write-Host ('BUILD OK: ' + $item.FullName + '  (' + [math]::Round($item.Length / 1MB, 1) + ' MB, ' + $item.LastWriteTime + ')') -ForegroundColor Green
  if ($ShutdownWhenDone) {
    Write-Host 'Shutting down in 120 seconds. Cancel with: shutdown /a' -ForegroundColor Yellow
    shutdown /s /t 120 /c 'Vera release build finished'
  }
} else {
  Write-Host ''
  Write-Host ('BUILD FAILED (exit code ' + $exitCode + '). The computer stays on.') -ForegroundColor Red
  exit 1
}
